#!/usr/bin/env python3
"""Build the static values-ru overlay tree from translation data files."""

from __future__ import annotations

import argparse
import shutil
import sys
from pathlib import Path
from xml.sax.saxutils import escape

from common import (
    KIND_ARRAY,
    KIND_PLURALS,
    KIND_STRING,
    REPO_ROOT,
    iter_data_files,
    load_config,
    load_data_file,
    overlay_file_path,
    parse_entries,
)

HEADER = """<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by device/xiaomi/fuxi/translations/tools/build_overlay.py.
     Do not edit this file directly; edit the JSON data under translations/data/. -->
<resources xmlns:xliff="urn:oasis:names:tc:xliff:document:1.2">
"""

FOOTER = "</resources>\n"

KEEP_ATTRS = ("formatted", "product")


def xml_attr(value: str) -> str:
    return escape(value, {'"': "&quot;"})


def emit_string(name: str, attrs: dict, text: str) -> str:
    extra = "".join(
        f' {key}="{xml_attr(attrs[key])}"' for key in KEEP_ATTRS if key in attrs
    )
    return f'    <string name="{xml_attr(name)}"{extra}>{text}</string>\n'


def emit_plurals(name: str, attrs: dict, items: dict) -> str:
    extra = "".join(
        f' {key}="{xml_attr(attrs[key])}"' for key in KEEP_ATTRS if key in attrs
    )
    out = [f'    <plurals name="{xml_attr(name)}"{extra}>\n']
    for quantity in ("one", "few", "many", "other"):
        if quantity in items:
            out.append(f'        <item quantity="{quantity}">{items[quantity]}</item>\n')
    out.append("    </plurals>\n")
    return "".join(out)


def emit_array(tag: str, name: str, attrs: dict, items: list[str]) -> str:
    extra = "".join(
        f' {key}="{xml_attr(attrs[key])}"' for key in KEEP_ATTRS if key in attrs
    )
    out = [f'    <{tag} name="{xml_attr(name)}"{extra}>\n']
    for item in items:
        out.append(f"        <item>{item}</item>\n")
    out.append(f"    </{tag}>\n")
    return "".join(out)


def build() -> tuple[int, list[str]]:
    config = load_config()
    overlay_dir = REPO_ROOT / config["overlay_dir"]
    data_dir = REPO_ROOT / config["data_dir"]
    packages = {p["id"]: p for p in config["packages"]}

    written = 0
    errors: list[str] = []

    for data_path in iter_data_files(data_dir):
        rel = data_path.relative_to(data_dir)
        if len(rel.parts) != 3:
            errors.append(f"Unexpected data path: {data_path}")
            continue
        pkg_id, resdir_slug, filename = rel.parts
        package = packages.get(pkg_id)
        if not package:
            errors.append(f"Unknown package in data path: {pkg_id}")
            continue
        resdir = resdir_slug.replace("__", "/")
        if resdir not in package["resource_dirs"]:
            errors.append(f"Unknown resource dir {resdir} for {pkg_id}")
            continue

        source_name = Path(filename).stem + ".xml"
        source_file = REPO_ROOT / package["source"] / resdir / "values" / source_name
        if not source_file.exists():
            errors.append(f"Source file missing: {source_file}")
            continue

        data = load_data_file(data_path)
        source_entries = {e["name"]: e for e in parse_entries(source_file)}

        chunks = [HEADER]
        for entry in parse_entries(source_file):
            name = entry["name"]
            kind = entry["kind"]
            if kind == KIND_STRING:
                if name in data["strings"]:
                    chunks.append(
                        emit_string(name, entry["attrs"], data["strings"][name])
                    )
            elif kind == KIND_PLURALS:
                if name in data["plurals"]:
                    chunks.append(
                        emit_plurals(name, entry["attrs"], data["plurals"][name])
                    )
            elif kind == KIND_ARRAY:
                if name in data["arrays"]:
                    chunks.append(
                        emit_array(
                            entry["tag"], name, entry["attrs"], data["arrays"][name]
                        )
                    )
        chunks.append(FOOTER)

        for section, values in (
            ("strings", data["strings"]),
            ("plurals", data["plurals"]),
            ("arrays", data["arrays"]),
        ):
            for name in values:
                if name not in source_entries:
                    errors.append(
                        f"{data_path}: '{name}' from {section} not found in {source_file.name}"
                    )

        out_path = overlay_file_path(overlay_dir, package, resdir, source_name)
        out_path.parent.mkdir(parents=True, exist_ok=True)
        out_path.write_text("".join(chunks), encoding="utf-8")
        written += 1

    return written, errors


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--clean",
        action="store_true",
        help="remove the generated overlay tree before rebuilding",
    )
    args = parser.parse_args()

    config = load_config()
    if args.clean:
        overlay_dir = REPO_ROOT / config["overlay_dir"]
        if overlay_dir.exists():
            shutil.rmtree(overlay_dir)
        print(f"Removed {overlay_dir}")

    written, errors = build()
    print(f"Generated {written} values-ru XML file(s) under {config['overlay_dir']}")
    if errors:
        print("\nErrors:", file=sys.stderr)
        for error in errors:
            print(f"  - {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
